const $=id=>document.getElementById(id),colors=['#00f5e9','#fa42c6','#ffcf39','#8d69ff','#f05a44'];let state,selected=0,hover=null,armed=false,previous=null,sound=false,ac,toastTimer;let selectedDifficulty='beginner';try{if(localStorage.getItem('flux-difficulty')==='challenger')selectedDifficulty='challenger'}catch{}let best=0;let records=[],storageOK=true,scoreSort='best',drag=null,suppressClick=0;try{records=sanitizeRecords(JSON.parse(localStorage.getItem('flux-history-v1')||'[]'))}catch{storageOK=false;}let effects=!matchMedia("(prefers-reduced-motion: reduce)").matches,cinemaTimer;
