document.addEventListener('keydown',e=>{if(document.body.classList.contains('home-mode')||document.querySelector('dialog[open]')||drag||e.ctrlKey||e.metaKey||e.altKey)return;let k=e.key.toLowerCase();if(['1','2','3'].includes(k)){e.preventDefault();select(+k-1)}else if(k==='r'&&state.difficulty!=='challenger')$('rotate').click();else if(k==='z'&&state.difficulty!=='challenger')$('undo').click();else if(k==='escape'){armed=false;render()}else if(k.startsWith('arrow')){e.preventDefault();hover??=[0,0];let [x,y]=hover;if(k==='arrowleft')x--;if(k==='arrowright')x++;if(k==='arrowup')y--;if(k==='arrowdown')y++;hover=[Math.max(0,Math.min(7,x)),Math.max(0,Math.min(7,y))];$('board').focus();paint()}else if((k==='enter'||k===' ')&&document.activeElement===$('board')){e.preventDefault();hover??=[0,0];place(...hover)}});$('effects').onclick=()=>{effects=!effects;document.body.classList.toggle('low-fx',!effects);$('effects').setAttribute('aria-label',effects?'Efektleri azalt':'Efektleri aç');if(!effects){$('cinema').classList.remove('active');$('fx-layer').replaceChildren()}};
function makeId(){return typeof crypto.randomUUID==='function'?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2)}
function updateStorageNote(){$('storage-note').textContent=storageOK?'Puanların ve devam eden oyunun bu tarayıcıda saklanır.':'Tarayıcı kaydı kullanılamıyor. Oynayabilirsin; sayfa kapanınca ilerleme kaybolabilir.'}
