function archiveRound(status){if(!state||state.moves===0)return;records=recordRound(records,state,status,new Date().toISOString());persistHistory()}
function refreshHome(){for(const mode of ['beginner','challenger'])$('mode-'+mode).setAttribute('aria-pressed',String(selectedDifficulty===mode));$('home-best').textContent=best.toLocaleString('tr-TR');$('home-count').textContent=records.length;const playable=hasMoves(state.board,state.pieces,state.difficulty!=='challenger');$('continue-game').hidden=state.moves===0||!playable;$('continue-score').textContent=state.score.toLocaleString('tr-TR')+' PUAN · '+(state.difficulty==='challenger'?'CHALLENGER':'BEGINNER');updateStorageNote();drawScores()}
function showHome(){restartFlow.stop();cancelDrag();hover=null;armed=false;save();document.body.classList.add('home-mode');$('game-view').hidden=true;$('home-view').hidden=false;$('cinema').classList.remove('active');refreshHome();window.scrollTo(0,0)}
