$('home-button').onclick=showHome;$('home-brand').onclick=e=>{e.preventDefault();showHome()};$('continue-game').onclick=showGame;$('new-game').onclick=()=>{if(state.moves>0&&(hasMoves(state.board,state.pieces,state.difficulty!=='challenger')))$('confirm').showModal();else startNew(true)};$('scores-button').onclick=()=>{$('scores-view').classList.remove('hidden');drawScores();$('scores-view').scrollIntoView({block:'nearest'})};$('scores-close').onclick=()=>$('scores-view').classList.add('hidden');$('home-help').onclick=()=>$('dialog').showModal();for(const mode of ['best','recent'])$('sort-'+mode).onclick=()=>{scoreSort=mode;$('sort-best').setAttribute('aria-pressed',String(mode==='best'));$('sort-recent').setAttribute('aria-pressed',String(mode==='recent'));drawScores()};

for(const mode of ['beginner','challenger'])$('mode-'+mode).onclick=()=>{selectedDifficulty=mode;try{localStorage.setItem('flux-difficulty',mode)}catch{}refreshHome()};
const restartFlow=createRestartCountdown(n=>{$('restart-count').textContent=n+' saniye sonra yeni oyun…'},()=>startNew());
document.body.classList.toggle('low-fx',!effects);load();showHome();
